//! Source assertions are original fixture facts. Demux tuples are literal
//! public consumer33 observations, not generated by the proposed implementation.
mod common;
#[path = "support/demux.rs"]
mod support;
use std::sync::atomic::{AtomicBool, Ordering};
use triergon_core::{Budget, Error, WorkBudget};
use triergon_isobmff::{
    BuildStatus, SampleStep, SourceSeekLimits, SourceSeekPlanner, SourceSeekRequest, SourceTrack,
    compat::mov::{
        clock::ClockOrigin,
        packets::{CursorStatus, DemuxProfile, PacketOccurrence},
        seek::{IndexCursor, IndexEntry, IndexLimits, SeekJob, SeekLimits, SeekPlan},
    },
};
fn index(pool: &Budget, movie: &support::Movie, quantum: u64) -> Vec<IndexEntry> {
    let sources = movie.demux();
    let baseline = pool.used();
    let mut cursor = IndexCursor::new_complete_source(
        pool,
        sources[0],
        &movie.media,
        IndexLimits::default(),
        DemuxProfile::NoParseNoFillin,
    )
    .unwrap();
    assert_eq!(
        cursor
            .poll(&mut WorkBudget::new(0), &AtomicBool::new(false))
            .unwrap(),
        CursorStatus::Yield
    );
    let mut rows = Vec::new();
    let mut end = false;
    for _ in 0..4096 {
        match cursor
            .poll(&mut WorkBudget::new(quantum), &AtomicBool::new(false))
            .unwrap()
        {
            CursorStatus::Yield => {}
            CursorStatus::End => {
                end = true;
                break;
            }
            CursorStatus::Ready => {
                let held = pool.used();
                assert_eq!(
                    cursor
                        .poll(&mut WorkBudget::new(0), &AtomicBool::new(false))
                        .unwrap(),
                    CursorStatus::Ready
                );
                assert_eq!(pool.used(), held);
                rows.push(cursor.take_entry().unwrap());
            }
        }
    }
    assert!(end, "native index did not resume within fixed bound");
    drop(cursor);
    assert_eq!(pool.used(), baseline);
    rows
}
fn plan<'a>(pool: &Budget, movie: &'a support::Movie, ticks: i64) -> SeekPlan<'a> {
    let tracks = movie.demux();
    let mut job = SeekJob::new_complete_source(
        pool,
        tracks[0],
        &movie.media,
        ticks,
        SeekLimits::default(),
        DemuxProfile::NoParseNoFillin,
    )
    .unwrap();
    assert_eq!(
        job.poll(&mut WorkBudget::new(0), &AtomicBool::new(false))
            .unwrap(),
        BuildStatus::Yield
    );
    for _ in 0..4096 {
        if job
            .poll(&mut WorkBudget::new(1), &AtomicBool::new(false))
            .unwrap()
            == BuildStatus::Ready
        {
            return job.finish().unwrap();
        }
    }
    panic!("native seek planning did not resume within fixed bound");
}
fn replay(plan: &SeekPlan<'_>) -> Vec<PacketOccurrence> {
    let mut cursor = plan.cursor().unwrap();
    let mut out = Vec::new();
    for _ in 0..4096 {
        match cursor
            .poll(&mut WorkBudget::new(1), &AtomicBool::new(false))
            .unwrap()
        {
            CursorStatus::Yield => {}
            CursorStatus::End => return out,
            CursorStatus::Ready => {
                assert_eq!(
                    cursor
                        .poll(&mut WorkBudget::new(0), &AtomicBool::new(false))
                        .unwrap(),
                    CursorStatus::Ready
                );
                out.push(cursor.take_occurrence().unwrap());
            }
        }
    }
    panic!("native seek replay did not resume within fixed bound");
}
#[test]
fn public_regular_index_fields_and_held_entries_match_actual_demux_snapshot() {
    let pool = Budget::new(2 * 1024 * 1024).unwrap();
    let movie = support::parse(&pool, include_bytes!("fixtures/r-front-stco.mov"));
    assert_eq!(movie.tracks[0].table.sample_count(), 6);
    let original = movie.tracks[0].table.raw().bytes().as_ref().to_vec();
    let expected = [
        (675, 0, 1, 12, 0),
        (687, 1000, 0, 12, 1),
        (699, 2000, 0, 12, 2),
        (711, 3000, 1, 12, 0),
        (723, 4000, 0, 12, 1),
        (735, 5000, 0, 12, 2),
    ];
    for quantum in [1, 4096] {
        let entries = index(&pool, &movie, quantum);
        assert_eq!(entries.len(), 6);
        for (i, (actual, wanted)) in entries.iter().zip(expected).enumerate() {
            assert_eq!(
                (
                    actual.position,
                    actual.timestamp,
                    actual.flags,
                    actual.size,
                    actual.min_distance
                ),
                wanted
            );
            assert_eq!(actual.ordinal, i as u64);
            assert_eq!(actual.occurrence.source.ordinal, i as u64 + 1);
            assert_eq!(actual.occurrence.source.dts_ticks, Some(i as i128 * 1000));
        }
    }
    assert_eq!(movie.tracks[0].table.raw().bytes().as_ref(), original);
}
#[test]
fn public_fragment_index_distance_and_original_unsigned_clock_facts_match_snapshot() {
    let pool = Budget::new(2 * 1024 * 1024).unwrap();
    let movie = support::parse(&pool, include_bytes!("fixtures/f-tfra-mfra.mp4"));
    assert_eq!(movie.fragments.len(), 2);
    assert_eq!(movie.fragments[1].decode_time().unwrap().ticks(), 3000);
    let before: Vec<_> = movie
        .fragments
        .iter()
        .map(|f| f.raw().bytes().as_ref().to_vec())
        .collect();
    let rows = index(&pool, &movie, 1);
    let expected = [
        (763, 0, 1, 12, 0),
        (775, 1000, 0, 12, 0),
        (787, 2000, 0, 12, 1),
        (955, 3000, 1, 12, 0),
        (967, 4000, 0, 12, 0),
        (979, 5000, 0, 12, 1),
    ];
    assert_eq!(rows.len(), 6);
    for (row, wanted) in rows.iter().zip(expected) {
        assert_eq!(
            (
                row.position,
                row.timestamp,
                row.flags,
                row.size,
                row.min_distance
            ),
            wanted
        );
        assert!(row.occurrence.source.fragment_flags.is_some());
    }
    for (f, raw) in movie.fragments.iter().zip(before) {
        assert_eq!(f.raw().bytes().as_ref(), raw);
    }
}
#[test]
fn backward_demux_seek_replays_regular_front_and_end_moov_without_source_filtering() {
    for bytes in [
        include_bytes!("fixtures/r-front-stco.mov").as_slice(),
        include_bytes!("fixtures/r-end-co64.mov").as_slice(),
    ] {
        let pool = Budget::new(2 * 1024 * 1024).unwrap();
        let movie = support::parse(&pool, bytes);
        let before = movie.tracks[0].table.raw().bytes().as_ref().to_vec();
        let plan = plan(&pool, &movie, 1500);
        assert_eq!(plan.landing().selected.occurrence.source.ordinal, 1);
        assert!(!plan.landing().used_first_fallback);
        let rows = replay(&plan);
        assert_eq!(rows.len(), 6);
        assert_eq!(
            rows.iter().map(|r| r.source.ordinal).collect::<Vec<_>>(),
            [1, 2, 3, 4, 5, 6]
        );
        assert_eq!(
            rows.iter()
                .take(4)
                .map(|r| r.demux.dts_field.signed_ticks())
                .collect::<Vec<_>>(),
            [0, 1000, 2000, 3000]
        );
        assert_eq!(movie.tracks[0].table.raw().bytes().as_ref(), before);
    }
}
#[test]
fn demux_seek_configuration_return_uses_real_original_sample_ranges() {
    let pool = Budget::new(2 * 1024 * 1024).unwrap();
    let movie = support::parse(&pool, include_bytes!("fixtures/r-description-change.mov"));
    let raw: Vec<_> = movie.tracks[0]
        .table
        .descriptions()
        .iter()
        .map(|d| d.raw().bytes().as_ref().to_vec())
        .collect();
    let plan = plan(&pool, &movie, 5500);
    assert_eq!(plan.landing().selected.occurrence.source.ordinal, 4);
    let rows = replay(&plan);
    assert_eq!(
        rows.iter()
            .map(|r| (
                r.source.ordinal,
                r.source.description_index,
                r.source.range.start,
                r.demux.dts_field.signed_ticks()
            ))
            .collect::<Vec<_>>(),
        [(4, 2, 815, 3000), (5, 1, 833, 4000), (6, 1, 845, 5000)]
    );
    for (d, expected) in movie.tracks[0].table.descriptions().iter().zip(raw) {
        assert_eq!(d.raw().bytes().as_ref(), expected);
    }
}
#[test]
fn signed_cts_demux_clock_selection_preserves_version_bits_and_source_time() {
    let pool = Budget::new(2 * 1024 * 1024).unwrap();
    let movie = support::parse(&pool, include_bytes!("fixtures/r-ctts-v1.mov"));
    let mut source = movie.tracks[0].table.cursor();
    let first = loop {
        if let SampleStep::Sample(s) = source.poll(&mut WorkBudget::new(1)).unwrap() {
            break s;
        }
    };
    assert_eq!((first.dts_ticks, first.cts_ticks), (Some(0), Some(0)));
    assert_eq!(first.composition_offset.unwrap().version(), 1);
    let plan = plan(&pool, &movie, 1500);
    let rows = replay(&plan);
    assert_eq!(rows.len(), 6);
    assert_eq!(
        (
            rows[0].source.dts_ticks,
            rows[0].demux.dts_field.signed_ticks(),
            rows[0].demux.pts_field.signed_ticks()
        ),
        (Some(0), -1000, 0)
    );
    assert_eq!(
        (rows[2].source.dts_ticks, rows[2].source.cts_ticks),
        (Some(2000), Some(1000))
    );
    assert_eq!(
        rows[2].source.composition_offset.unwrap().raw_bits(),
        4294966296
    );
    assert_eq!(rows[2].source.composition_offset.unwrap().version(), 1);
}
#[test]
fn demux_empty_stss_fallback_does_not_change_source_sync_or_source_seek_refusal() {
    let pool = Budget::new(2 * 1024 * 1024).unwrap();
    let movie = support::parse(&pool, include_bytes!("fixtures/r-stss-empty.mov"));
    assert_eq!(movie.tracks[0].table.sync_entry_count(), Some(0));
    let source = SourceTrack::new(1, Some(&movie.tracks[0].table), &movie.fragments).unwrap();
    let mut source_job = SourceSeekPlanner::new(
        source,
        SourceSeekRequest {
            target_ordinal: 2,
            preroll_samples: 0,
        },
        &movie.media,
        SourceSeekLimits::default(),
    )
    .unwrap();
    let mut source_error = None;
    for _ in 0..4096 {
        match source_job.poll(&mut WorkBudget::new(1), &AtomicBool::new(false)) {
            Err(e) => {
                source_error = Some(e);
                break;
            }
            Ok(BuildStatus::Ready) => panic!("source sync fabricated"),
            Ok(BuildStatus::Yield) => {}
        }
    }
    assert!(matches!(source_error, Some(Error::Unsupported(_))));
    let plan = plan(&pool, &movie, 1500);
    let rows = replay(&plan);
    assert_eq!(rows[0].source.ordinal, 1);
    assert!(!rows[0].source.is_container_sync());
    assert_eq!(rows[0].demux.flags, 1);
}
#[test]
fn absent_fragment_origin_stays_unknown_through_explicit_demux_seek_and_replay() {
    let pool = Budget::new(2 * 1024 * 1024).unwrap();
    let movie = support::parse(&pool, include_bytes!("fixtures/f-no-second-tfdt.mp4"));
    assert!(movie.fragments[1].decode_time().is_none());
    let plan = plan(&pool, &movie, 3500);
    assert_eq!(plan.landing().selected.occurrence.source.ordinal, 4);
    let rows = replay(&plan);
    assert_eq!(rows.len(), 3);
    for (r, expected) in rows.iter().zip([3000, 4000, 5000]) {
        assert_eq!(r.source.dts_ticks, None);
        assert_eq!(r.source.cts_ticks, None);
        assert_eq!(r.demux.dts_field.signed_ticks(), expected);
        assert!(matches!(r.clock_origin, ClockOrigin::PredecessorEnd(_)));
    }
    assert!(movie.fragments[1].decode_time().is_none());
}
#[test]
fn demux_index_limit_and_cancellation_failures_are_sticky_without_storage_leak() {
    let pool = Budget::new(2 * 1024 * 1024).unwrap();
    let movie = support::parse(&pool, include_bytes!("fixtures/r-front-stco.mov"));
    let tracks = movie.demux();
    let baseline = pool.used();
    let limits = IndexLimits {
        max_entries: 2,
        ..IndexLimits::default()
    };
    let mut job = IndexCursor::new_complete_source(
        &pool,
        tracks[0],
        &movie.media,
        limits,
        DemuxProfile::NoParseNoFillin,
    )
    .unwrap();
    let mut error = None;
    for _ in 0..4096 {
        match job.poll(&mut WorkBudget::new(1), &AtomicBool::new(false)) {
            Ok(CursorStatus::Ready) => {
                job.take_entry().unwrap();
            }
            Ok(CursorStatus::Yield) => {}
            Ok(CursorStatus::End) => panic!("entry cap silently truncated"),
            Err(e) => {
                error = Some(e);
                break;
            }
        }
    }
    let error = error.unwrap();
    assert!(matches!(error, Error::Limit { .. }));
    assert_eq!(
        job.poll(&mut WorkBudget::new(4096), &AtomicBool::new(false)),
        Err(error)
    );
    drop(job);
    assert_eq!(pool.used(), baseline);
    let mut seek = SeekJob::new_complete_source(
        &pool,
        tracks[0],
        &movie.media,
        1500,
        SeekLimits::default(),
        DemuxProfile::NoParseNoFillin,
    )
    .unwrap();
    let cancel = AtomicBool::new(true);
    assert_eq!(
        seek.poll(&mut WorkBudget::new(1), &cancel),
        Err(Error::Cancelled)
    );
    cancel.store(false, Ordering::Relaxed);
    assert_eq!(
        seek.poll(&mut WorkBudget::new(4096), &cancel),
        Err(Error::Cancelled)
    );
    drop(seek);
    assert_eq!(pool.used(), baseline);
}
